.signed-bar::after {
  content: "";
  position: absolute;
  left: 0;
  top: -3px;
  bottom: -3px;
  width: 1px;
  background: var(--muted);
}
.signed-bar > span {
  position: absolute;
  left: 0;
  height: 100%;
  background: var(--accent);
}
.signed-bar > span.negative {
  left: auto;
  right: 50%;
  opacity: 0.65;
}
.signed-bar.signed::after,
.signed-bar.signed > span:not(.negative) {
  left: 50%;
}
