  }
  function show(index: number, target: EventTarget | null) {
    if (!(target instanceof Element)) return;
    keepOpen();
    const bounds = target.getBoundingClientRect();
    anchor = target;
    anchorTop = bounds.top;
    tooltip = {
      index,
